parameters.jsCode:
const items = $input.all();
const results = [];

items.forEach((item, index) => {
  let candidate = {};
  try {
    candidate = $('Listar Candidatos1').all()[index]?.json || {};
  } catch (e) {
    try {
      candidate = $('Listar Candidatos1').itemMatching(index)?.json || {};
    } catch (e2) {
      candidate = item.json?.candidate || item.json || {};
    }
  }

  const aiRaw = item.json || {};
  let rawData = aiRaw.output?.[0]?.content?.[0]?.text || aiRaw.text || aiRaw.message?.content || aiRaw.output || aiRaw;

  let parsed = {
    funnel_step: "geral",
    message: null,
    buttons: null
  };

  try {
    if (typeof rawData === "string") {
      const start = rawData.indexOf("{");
      const end = rawData.lastIndexOf("}");
      if (start >= 0 && end >= 0) {
        parsed = JSON.parse(rawData.substring(start, end + 1));
      }
    } else if (typeof rawData === "object" && rawData !== null) {
      parsed = rawData;
    }
  } catch (e) {}

  // 🛡️ Expurgo de robôs/cardápios ou mensagens vazias
  if (parsed.funnel_step === "ignorar" || !parsed.message || String(parsed.message).trim() === "") {
    return; // Não gera registro para enfileirar
  }

  let buttonsObj = null;
  if (Array.isArray(parsed.buttons) && parsed.buttons.length > 0) {
    buttonsObj = {
      tipo: "botoes",
      opcoes: parsed.buttons
    };
  }

  results.push({
    json: {
      queue_id: candidate.queue_id,
      conversation_id: candidate.conversation_id,
      phone: candidate.phone,
      company_name: candidate.company_name,
      funnel_step: parsed.funnel_step || "geral",
      message: String(parsed.message).trim(),
      interactive_buttons: buttonsObj
    }
  });
});

return results;
